(1, 1, 'Kertas HVS A4 80gr (500 lembar)', 'kertas-hvs-a4-80gr-500-lembar', 'Kertas HVS putih bersih untuk print hitam/warna, isi 1 rim.', '/images/kertasHVSA480gr(500lembar).jpg', '52000.00', 100, 0, '2025-12-28 09:36:47', '2025-12-28 09:36:47'),
