(5, 2, 'Pulpen Gel 0.5mm Hitam', 'pulpen-gel-05mm-hitam', 'Pulpen gel halus untuk menulis harian dan tanda tangan.', '/images/pulpenGel0.5mmHitam.jpg', '6000.00', 100, 0, '2025-12-28 09:36:47', '2025-12-28 09:36:47'),
(6, 2, 'Pensil 2B + Penghapus', 'pensil-2b-penghapus', 'Pensil 2B untuk ujian dan sketsa dilengkapi penghapus.', '/images/pensilpenghapus.jpg', '4000.00', 100, 0, '2025-12-28 09:36:47', '2025-12-28 09:36:47'),
