(9, 3, 'Map Snelhecter Folio', 'map-snelhecter-folio', 'Map snelhecter plastik tebal untuk menyimpan dokumen folio.', '/images/mapSnelhecterFolio.jpg', '3500.00', 100, 0, '2025-12-28 09:36:47', '2025-12-28 09:36:47'),
